const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const projectId = String(payload.projectId || payload.id || '').trim();
const milestoneCode = String(payload.milestoneCode || payload.milestone || 'M1').toUpperCase();
const prNumber = payload.prNumber ? Number(payload.prNumber) : null;
const commitSha = String(payload.commitSha || payload.sha || 'staging-head').substring(0, 7);
const notes = String(payload.notes || payload.description || `Milestone ${milestoneCode} deliverable released`).trim();

const allPhases = ['M1', 'M2', 'M3', 'M4'];
const phaseWeights = { M1: 25, M2: 50, M3: 75, M4: 100 };
const currentWeight = phaseWeights[milestoneCode] || 25;
const completedIndex = allPhases.indexOf(milestoneCode);
const nextPhase = completedIndex >= 0 && completedIndex < allPhases.length - 1 ? allPhases[completedIndex + 1] : 'COMPLETED_DELIVERY';

const milestoneRecord = {
  milestoneCode,
  status: 'COMPLETED',
  progressPercent: currentWeight,
  nextPhase,
  completedAt: new Date().toISOString(),
  verificationSource: prNumber ? `GitHub PR #${prNumber} (${commitSha})` : 'Admin Sign-off',
  notes
};

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    projectId,
    milestoneRecord
  }
}];

const item = $input.first().json;
const m = item.milestoneRecord;
const projectId = item.projectId;

const dashboardState = {
  projectId,
  overallProgress: m.progressPercent,
  currentPhase: m.nextPhase === 'COMPLETED_DELIVERY' ? 'Final Acceptance' : m.nextPhase,
  lastCompletedPhase: m.milestoneCode,
  statusBadge: m.nextPhase === 'COMPLETED_DELIVERY' ? 'READY_FOR_HANDOVER' : 'IN_PROGRESS',
  deliverablesReadyForClientReview: true,
  actionRequiredFromClient: m.nextPhase === 'COMPLETED_DELIVERY' ? 'Submit Final Acceptance Sign-off' : 'Review Staging Build & Provide Feedback',
  lastUpdated: new Date().toISOString()
};

return [{
  json: {
    ...item,
    dashboardState
  }
}];

const item = $input.first().json;
const m = item.milestoneRecord;
const d = item.dashboardState;

const releaseCard = {
  title: `Deliverable Milestone ${m.milestoneCode} Released for ${item.projectId}`,
  summary: `Milestone ${m.milestoneCode} has been verified on staging. Project is now at ${m.progressPercent}% completion.`,
  stagingPreviewHost: `staging-${item.projectId.toLowerCase().replace(/[^a-z0-9]/g, '-')}.litops.app`,
  nextMilestoneTarget: m.nextPhase,
  acceptanceWindowDays: 5,
  escalationChannel: 'Vikash Saravanan (Lead System Engineer)',
  dispatchedChannels: ['Client Portal Notification', 'Email Digest Queue']
};

return [{
  json: {
    eventId: item.eventId,
    status: 'milestone_tracked',
    milestone: m,
    dashboardState: d,
    releaseNotification: releaseCard
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'milestone_tracked',
  detail: {
    milestone: item.json.milestone,
    dashboardState: item.json.dashboardState,
    releaseNotification: item.json.releaseNotification
  }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
